//! 🧪️ Actual factory sources retain their original Arc and physical ticket across producer interruption.
use semio_framework_value_factory::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::{sync::{Arc,atomic::{AtomicBool,AtomicUsize,Ordering}},alloc::Layout};
fn bank()->EffectBank{EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:usize::MAX>>2,maximum_capacity_bytes:usize::MAX>>2,maximum_release_bytes:usize::MAX>>2,maximum_depth:1<<10},1<<50))}
fn settle(poll:OriginalRetirementPoll)->RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("original factory fixture turn stayed pending")}}
fn drive(grant:RetainedCloneGrant,work:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll)->(RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>,(usize,usize),Option<usize>){let mut bank=bank();let((poll,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,work,operation));let _=bank.take_admitted();(settle(poll),heap,actual)}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(owner:&mut FactoryAuthority){for _ in 0..64{if owner.terminal_is_empty(){return}let d=owner.demands(4096).unwrap();let work=owner.next_computational_work(4096).unwrap();let(turn,heap,_)=drive(grant(d),work,|effect|owner.step(4096,effect));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty())}
#[test]
fn actual_factory_denial_null_attempt_and_separate_original_transfer_preserve_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();let source:Arc<dyn FactoryRetirement>=Arc::new(AtomicBool::new(false));let pointer=Arc::as_ptr(&source)as*const();let mut owner=FactoryAuthority::new(source.clone());let demand=owner.demands(4096).unwrap();let(turn,heap,actual)=drive(grant(demand),0,|effect|owner.step(4096,effect));assert!(turn.result.is_ok());assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(actual,None);assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),pointer);assert!(!owner.has_ticket());
 let mut refusing=bank();let(((poll,actual),attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||refusing.run(grant(demand),1,|effect|owner.step(4096,effect))));let _=refusing.take_admitted();let turn=settle(poll);assert_eq!(attempts,fixture["cases"][1]["attempts"].as_u64().unwrap()as usize);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap_err().primary().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),pointer);assert!(!owner.has_ticket());
 let(turn,heap,actual)=drive(grant(demand),1,|effect|owner.step(4096,effect));let p=turn.result.unwrap().progress();assert_eq!(heap,(demand.capacity_bytes,0));assert_eq!(actual,Some(demand.capacity_bytes));assert_eq!(p.retained_capacity_bytes,demand.capacity_bytes);assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),pointer);assert!(owner.has_ticket());assert_eq!(Arc::strong_count(&source),2);
 let transfer=owner.demands(4096).unwrap();assert_eq!(transfer.capacity_bytes,0);assert_eq!(drive(grant(transfer),0,|effect|owner.step(4096,effect)).0.work,0);assert!(owner.original().is_some());let(turn,heap,actual)=drive(grant(transfer),1,|effect|owner.step(4096,effect));assert_eq!(turn.work,u128::from(fixture["transferWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress().copied_bytes,transfer.copy_bytes);assert_eq!(heap,(0,0));assert_eq!(actual,None);assert!(owner.original().is_none());assert_eq!(Arc::strong_count(&source),2);close(&mut owner);assert_eq!(Arc::strong_count(&source),1);
}
struct Interrupting{calls:AtomicUsize,interrupt:AtomicBool,refusal:std::sync::Mutex<Option<ValueError>>}
struct Ticket{source:Option<Arc<Interrupting>>}
impl FactoryRetirementTicket for Ticket{
 fn preparation_work_demand(&self,_:usize)->Result<u64,ValueError>{Ok(0)}
 fn preparation_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 fn prepare_step(&mut self,_:usize,_:&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}
 fn preparation_is_complete(&self)->bool{true}
 fn original_slot(&mut self)->Option<&mut dyn std::any::Any>{Some(&mut self.source)}
}
impl ErasedSnapshotRetirement for Ticket{
 fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(u64::from(self.source.is_some()))}
 fn close_step(&mut self,_:usize,effect:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{let done=|result,work|RetainedWorkPoll::Complete(RetainedWorkOutcome{result,work});if self.source.is_none(){return done(Ok(RetainedCloneStep::Complete(Default::default())),0)}if effect.maximum_work_units()<1||effect.grant().maximum_items==0{return done(Ok(RetainedCloneStep::Progress(Default::default())),0)}assert!(effect.performed(1).unwrap());self.source.take();done(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,..Default::default()})),1)}
 fn native_header_release(&self)->Option<semio_framework_value_retirement::RetirementHeaderRelease>{self.terminal_is_empty().then(||unsafe{semio_framework_value_retirement::RetirementHeaderRelease::native(self,0,0)})}
 fn terminal_is_empty(&self)->bool{self.source.is_none()}
 fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.source.is_some()))}
}
impl FactoryRetirement for Interrupting{
 fn factory_retirement_work_demand(&self)->Result<u64,ValueError>{Ok(1)}
 fn factory_retirement_birth_bytes(&self)->usize{size_of::<Ticket>()}
 fn factory_retirement_copy_byte_demand(&self)->usize{0}
 fn factory_retirement_depth_demand(&self)->usize{1}
 fn prepare_factory_retirement<'reply>(&self,effect:&mut RetainedAllocationEffect<'_>,mut reply:FactoryProducerReply<'reply,dyn FactoryRetirementTicket,ValueError>)->FactoryProducerReplyComplete<'reply,ValueError>{self.calls.fetch_add(1,Ordering::Relaxed);*effect.actual()=Some(0);assert!(reply.performed(effect,1).unwrap());let pointer=unsafe{std::alloc::alloc(Layout::new::<Ticket>())}.cast::<Ticket>();assert!(!pointer.is_null());*effect.actual()=Some(size_of::<Ticket>());let ticket=unsafe{pointer.write(Ticket{source:None});Box::from_raw(pointer)};reply.publish(ticket);let progress=RetainedCloneProgress{retained_capacity_bytes:size_of::<Ticket>(),..Default::default()};let result=self.refusal.lock().unwrap().take().map_or(Ok(progress),|error|Err(error.with_retained_progress(progress)));let complete=reply.complete(RetainedWorkOutcome{result,work:1});if self.interrupt.swap(false,Ordering::Relaxed){panic!("original factory reply recorded before unwind")}complete}
 fn recover_factory_retirement<'reply>(&self,_effect:&mut RetainedAllocationEffect<'_>,_reply:FactoryProducerReply<'reply,dyn FactoryRetirementTicket,ValueError>)->FactoryProducerReplyComplete<'reply,ValueError>{panic!("already-recorded original factory producer must not run again")}
 fn transfer_factory_original(self:Arc<Self>,ticket:&mut dyn FactoryRetirementTicket)->Result<(),Arc<dyn FactoryRetirement>>{let Some(slot)=ticket.original_slot().and_then(|slot|slot.downcast_mut::<Option<Arc<Self>>>())else{return Err(self)};if slot.is_some(){return Err(self)}*slot=Some(self);Ok(())}
}
#[test]
fn actual_recorded_factory_reply_and_ticket_survive_unwind_without_replaying_producer(){
 let source=Arc::new(Interrupting{calls:AtomicUsize::new(0),interrupt:AtomicBool::new(true),refusal:std::sync::Mutex::new(None)});let pointer=Arc::as_ptr(&source).cast::<()>();let mut owner=FactoryAuthority::new(source.clone());let demand=owner.demands(4096).unwrap();let mut unwound=bank();let spent_before=unwound.wallet().remaining_work();let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||unwound.run(grant(demand),1,|effect|owner.step(4096,effect))));assert!(result.is_err());let actual=unwound.actual();assert_eq!(actual,Some(size_of::<Ticket>()));assert!(owner.has_ticket());assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),pointer);assert_eq!(source.calls.load(Ordering::Relaxed),1);let((poll,untouched),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||unwound.run(grant(demand),1,|effect|owner.step(4096,effect)));let _=unwound.take_admitted();let turn=settle(poll);assert_eq!(turn.result.unwrap().progress().retained_capacity_bytes,size_of::<Ticket>());assert_eq!(turn.work,0);assert_eq!(spent_before-unwound.wallet().remaining_work(),1);assert_eq!(heap,(0,0));assert_eq!(untouched,Some(size_of::<Ticket>()));assert!(owner.original().is_some());assert_eq!(source.calls.load(Ordering::Relaxed),1);close(&mut owner);assert_eq!(source.calls.load(Ordering::Relaxed),1);assert_eq!(Arc::strong_count(&source),1);
}

fn close_value<T:RetireOwned>(value:T){let mut original=Some(value);let d=retirement::controlled::controlled_retirement_birth_demand(original.as_ref().unwrap()).unwrap();let mut admission=bank();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||admission.run_outcome(grant(d),1,|effect|retirement::admit_owned_retirement(&mut original,effect)));let _=admission.take_admitted();let(owner,p)=turn.result.unwrap().unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(original.is_none());let mut slot=Some(owner);for _ in 0..128{if slot.is_none(){return}let d=factory_ticket_demands(slot.as_ref().unwrap(),4096).unwrap();let work=if slot.as_ref().unwrap().terminal_is_empty(){1}else{slot.as_ref().unwrap().next_computational_work(4096).unwrap()};let turn=semio_framework_value_clone_source_testing::drive::drive(grant(d),work,|effect|close_factory_ticket(&mut slot,4096,effect));turn.result.unwrap();}assert!(slot.is_none())}
#[test]
fn actual_partial_ticket_and_original_refusal_survive_producer_unwind_together(){
 let error=ValueError::new(ValueRefusalKind::Canceled,"original factory producer refusal 源");let error_pointer=error.message.as_ptr();let source=Arc::new(Interrupting{calls:AtomicUsize::new(0),interrupt:AtomicBool::new(true),refusal:std::sync::Mutex::new(Some(error))});let source_pointer=Arc::as_ptr(&source).cast::<()>();let mut owner=FactoryAuthority::new(source.clone());let demand=owner.demands(4096).unwrap();let mut unwound=bank();let spent_before=unwound.wallet().remaining_work();assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||unwound.run(grant(demand),1,|effect|owner.step(4096,effect)))).is_err());let actual=unwound.actual();assert_eq!(actual,Some(size_of::<Ticket>()));assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),source_pointer);assert!(owner.has_ticket());let((poll,untouched),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||unwound.run(grant(demand),1,|effect|owner.step(4096,effect)));let _=unwound.take_admitted();let turn=settle(poll);let failure=turn.result.unwrap_err();assert_eq!(failure.primary().unwrap().message.as_ptr(),error_pointer);assert_eq!(failure.retained_progress().retained_capacity_bytes,size_of::<Ticket>());assert_eq!(heap,(0,0));assert_eq!(source.calls.load(Ordering::Relaxed),1);assert!(owner.original().is_some()&&owner.has_ticket());
 let d=owner.demands(4096).unwrap();assert_eq!(d.release_bytes,size_of::<Ticket>());let work=owner.next_computational_work(4096).unwrap();assert_eq!(work,1);let(turn,heap,actual)=drive(grant(d),work,|effect|owner.step(4096,effect));assert_eq!(turn.result.unwrap().progress().released_bytes,size_of::<Ticket>());assert_eq!(heap,(0,size_of::<Ticket>()));assert!(!owner.has_ticket());assert_eq!(Arc::as_ptr(owner.original().unwrap())as*const(),source_pointer);assert_eq!(source.calls.load(Ordering::Relaxed),1);close_value(failure);close(&mut owner);assert_eq!(source.calls.load(Ordering::Relaxed),2);assert_eq!(Arc::strong_count(&source),1);
}
